/**
 * LAYER 1 - Python semantics: exceptions, tracebacks, SystemExit, interpreter exit.
 *
 * This module knows nothing about `construct`, about argument parsing, or about the
 * program being ported. It models three things CPython gives you for free:
 *
 *   1. `PyException` - an exception that carries a *fully qualified Python type name*,
 *      a possibly multi-line message, a list of traceback frames, and a `__context__`
 *      chain (the "During handling of the above exception..." link).
 *   2. `formatException()` - a PURE function rendering an exception the way CPython's
 *      `traceback` module does. Pure => independently unit-testable, no I/O.
 *   3. `SystemExit` + `runMain()` - the process boundary. `SystemExit` carries the exact
 *      byte stream routing (stdout vs stderr) as data rather than performing I/O, so the
 *      CLI layer can be tested without capturing real file descriptors.
 *
 * Frame model
 * -----------
 * `pyFrames` is stored in *print order*: outermost (module level) first, innermost
 * (the `raise` site) last - exactly how CPython prints "most recent call last".
 * As an exception unwinds, each function it passes through contributes one frame to the
 * *front* of the list. `withFrame()` emulates that, and callers use it in a
 * `catch { throw withFrame(exc, MY_FRAME); }` idiom.
 */

/** A traceback frame. `source`/`anchor` are optional (PyInstaller strips library source). */
export function frame(file, line, name, source = null, anchor = null) {
  return { file, line, name, source, anchor };
}

/**
 * Build the `^^^^` anchor descriptor CPython 3.11+ prints under the failing
 * sub-expression. `offset` is a 0-based column inside the *stripped* source line.
 */
export function anchorFor(source, subExpression) {
  const offset = source.indexOf(subExpression);
  if (offset < 0) return null;
  return { offset, length: subExpression.length };
}

/** Base class for every emulated Python exception. */
export class PyException extends Error {
  /**
   * @param {string} pyType fully qualified Python name, e.g. "struct.error".
   * @param {string} pyMessage `str(exc)` - may contain embedded newlines.
   */
  constructor(pyType, pyMessage) {
    super(`${pyType}: ${pyMessage}`);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    /** @type {Array<object>} outermost-first */
    this.pyFrames = [];
    /** @type {PyException|null} CPython's `__context__` */
    this.pyContext = null;
  }
}

/** Python's `struct.error`, raised by the stdlib `struct` module's pack/unpack. */
export class StructError extends PyException {
  constructor(message) {
    super('struct.error', message);
  }
}

/**
 * Emulate the interpreter recording one more stack frame as `exc` unwinds outward.
 * Returns `exc` so it can be used directly in `throw withFrame(exc, F)`.
 * Non-Python errors (real JS bugs) pass through untouched.
 */
export function withFrame(exc, frameRecord) {
  if (exc instanceof PyException) exc.pyFrames.unshift(frameRecord);
  return exc;
}

/**
 * Render an exception exactly like CPython's default `sys.excepthook`.
 * PURE: returns the text (always newline-terminated), writes nothing.
 */
export function formatException(exc) {
  let out = '';
  if (exc.pyContext) {
    out += formatException(exc.pyContext);
    out += '\nDuring handling of the above exception, another exception occurred:\n\n';
  }
  out += 'Traceback (most recent call last):\n';
  for (const f of exc.pyFrames) {
    out += `  File "${f.file}", line ${f.line}, in ${f.name}\n`;
    if (f.source !== null) {
      out += `    ${f.source}\n`;
      if (f.anchor) {
        out += `    ${' '.repeat(f.anchor.offset)}${'^'.repeat(f.anchor.length)}\n`;
      }
    }
  }
  out += `${exc.pyType}: ${exc.pyMessage}\n`;
  return out;
}

/**
 * Python's `SystemExit`. Instead of writing to streams itself, it carries the output it
 * wants performed as an ordered list of `{ stream, text }` records. That keeps every
 * layer above it side-effect free and testable.
 */
export class SystemExit extends Error {
  /**
   * @param {number} code process exit status.
   * @param {Array<{stream: 'stdout'|'stderr', text: string}>} output
   */
  constructor(code, output = []) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
    this.output = output;
  }
}

/** Default sink: the real process streams. Swap for an array collector in tests. */
export function processStreams() {
  return {
    write(stream, text) {
      if (stream === 'stdout') process.stdout.write(text);
      else process.stderr.write(text);
    },
    setExitCode(code) {
      // Deliberately NOT `process.exit()`: on Linux, pipes are written asynchronously
      // and `process.exit()` would truncate the traceback / help text.
      process.exitCode = code;
    },
    pid: () => process.pid,
  };
}

/**
 * The `if __name__ == "__main__":` boundary, including the PyInstaller bootstrap's
 * unhandled-exception report.
 *
 * @param {() => void} main
 * @param {object}   options
 * @param {string}   options.scriptName name used by the PyInstaller "[PYI-...]" line.
 * @param {Array}    [options.callerFrames] frames of the emulated Python source between
 *                   the interpreter and the library call, outermost-first.
 * @param {object}   [options.streams] injectable I/O sink (see `processStreams`).
 */
export function runMain(main, options) {
  const { scriptName, callerFrames = [], streams = processStreams() } = options;
  try {
    main();
    streams.setExitCode(0);
  } catch (exc) {
    if (exc instanceof SystemExit) {
      for (const record of exc.output) streams.write(record.stream, record.text);
      streams.setExitCode(exc.code);
      return;
    }
    if (!(exc instanceof PyException)) throw exc;
    for (let i = callerFrames.length - 1; i >= 0; i -= 1) withFrame(exc, callerFrames[i]);
    streams.write('stderr', formatException(exc));
    streams.write(
      'stderr',
      `[PYI-${streams.pid()}:ERROR] Failed to execute script '${scriptName}' `
        + 'due to unhandled exception!\n',
    );
    streams.setExitCode(1);
  }
}

/**
 * LAYER 1 - Python semantics: `int(str)`.
 *
 * Reimplements CPython's string -> int conversion, including the parts most ports get
 * wrong. Returns a **BigInt** because Python integers are arbitrary precision and the
 * original magnitude must survive intact (an out-of-range value is echoed verbatim in
 * `construct`'s error message, so `1e21`-style precision loss is not acceptable).
 *
 * CPython's actual algorithm (`_PyLong_FromUnicodeObject`) has two paths, and the
 * difference is observable:
 *
 *   * Pure-ASCII input goes straight to `PyLong_FromString`, which strips only the
 *     C-locale space set `\t \n \v \f \r ' '`.
 *   * Any input containing a code point >= 127 is first run through
 *     `_PyUnicode_TransformDecimalAndSpaceToASCII`, which rewrites *only* code points
 *     >= 127: Unicode decimal digits (category Nd) become their ASCII digit, Unicode
 *     whitespace becomes a plain space, and anything else becomes an unconvertible
 *     marker. Code points < 127 are passed through untouched.
 *
 * That is why `int('\x1c5')` raises (0x1C is `str.isspace()` but not C-locale space)
 * while `int('\x855')` and `int('\xa05')` both yield 5, and why `int('﻿5')` raises
 * (U+FEFF is category Cf, not whitespace) but `int('１２')` yields 12.
 */

/** Code points < 127 are copied verbatim by CPython's transform step. */
const ASCII_TRANSFORM_LIMIT = 127;

/** The C-locale space set used by `PyLong_FromString` for stripping. */
const C_SPACE = new Set(['\t', '\n', '', '\f', '\r', ' ']);

/** `Py_UNICODE_ISSPACE` restricted to code points >= 127 (the only ones that matter). */
const UNICODE_SPACE_ABOVE_ASCII = new Set([
  0x0085, 0x00a0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006,
  0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

const DECIMAL_DIGIT = /\p{Nd}/u;

/** `[sign] digit (['_'] digit)*` - underscores only ever *between* digits. */
const DIGITS = /^[0-9](?:_?[0-9])*$/;

/**
 * `Py_UNICODE_TODECIMAL`: the numeric value 0-9 of a Unicode decimal digit, or -1.
 *
 * Unicode guarantees each decimal-digit set is encoded as ten consecutive code points
 * ascending from zero, so the value is the offset within the maximal contiguous run of
 * Nd code points, modulo 10. The modulo matters: several sets are adjacent with no gap
 * (e.g. U+1D7CE..U+1D7FF packs five sets back to back).
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30; // ASCII fast path
  if (!DECIMAL_DIGIT.test(String.fromCodePoint(codePoint))) return -1;
  let runStart = codePoint;
  while (runStart > 0 && DECIMAL_DIGIT.test(String.fromCodePoint(runStart - 1))) runStart -= 1;
  return (codePoint - runStart) % 10;
}

/**
 * `_PyUnicode_TransformDecimalAndSpaceToASCII`.
 * @returns {string|null} the ASCII-ised text, or null if a code point is unconvertible.
 */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint < ASCII_TRANSFORM_LIMIT) {
      out += character;
    } else if (UNICODE_SPACE_ABOVE_ASCII.has(codePoint)) {
      out += ' ';
    } else {
      const value = decimalValue(codePoint);
      // CPython substitutes '?' here; bailing out is equivalent because '?' can never
      // be stripped and can never satisfy the digit grammar.
      if (value < 0) return null;
      out += String(value);
    }
  }
  return out;
}

/**
 * Python's `int(text)` with the default base 10.
 * @returns {{ok: true, value: bigint}|{ok: false, value: null}} a rejection signal rather
 *          than a thrown error, so the CLI layer decides how to report it.
 */
export function pyInt(text) {
  const rejected = { ok: false, value: null };

  const ascii = transformDecimalAndSpaceToAscii(text);
  if (ascii === null) return rejected;

  let start = 0;
  let end = ascii.length;
  while (start < end && C_SPACE.has(ascii[start])) start += 1;
  while (end > start && C_SPACE.has(ascii[end - 1])) end -= 1;
  let body = ascii.slice(start, end);

  let negative = false;
  if (body.startsWith('+') || body.startsWith('-')) {
    negative = body[0] === '-';
    body = body.slice(1); // no whitespace may follow the sign
  }

  if (!DIGITS.test(body)) return rejected;

  const magnitude = BigInt(body.replace(/_/g, ''));
  return { ok: true, value: negative ? -magnitude : magnitude };
}

/**
 * LAYER 1 - Python semantics: `repr()` for `bytes` and `str`.
 *
 * `bytesRepr` operates on a PLAIN JavaScript Array of integers 0..255 - no typed arrays,
 * no byte-buffer objects of any kind. `strRepr` is here too because it is the same
 * algorithm (quote selection + escape table) over code points instead of bytes; the CLI
 * layer needs it to echo rejected values in `invalid int value: '...'` messages.
 *
 * Quote selection, as implemented by CPython:
 *   * default to `'`;
 *   * switch to `"` only if the value contains `'` and does NOT contain `"`;
 *   * otherwise keep `'` and backslash-escape any `'` (a `"` stays literal).
 */

const SINGLE = 0x27;
const DOUBLE = 0x22;
const BACKSLASH = 0x5c;

/** The three short escapes CPython emits; every other control byte becomes `\xNN`. */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/** Pick the quote character, given whether the value contains `'` and `"`. */
function chooseQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? DOUBLE : SINGLE;
}

function hex2(value) {
  return `\\x${value.toString(16).padStart(2, '0')}`;
}

/**
 * `repr(bytes)`.
 * @param {number[]} byteValues plain array of integers 0..255.
 * @returns {string} e.g. `b'\x10\xa1'`, `b'!l'`, `b"'A"`.
 */
export function bytesRepr(byteValues) {
  const quote = chooseQuote(byteValues.includes(SINGLE), byteValues.includes(DOUBLE));
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const byteValue of byteValues) {
    if (byteValue === BACKSLASH) {
      body += '\\\\';
    } else if (byteValue === quote) {
      body += `\\${quoteChar}`;
    } else if (byteValue >= 0x20 && byteValue <= 0x7e) {
      body += String.fromCharCode(byteValue);
    } else if (SHORT_ESCAPES.has(byteValue)) {
      body += SHORT_ESCAPES.get(byteValue);
    } else {
      body += hex2(byteValue);
    }
  }
  return `b${quoteChar}${body}${quoteChar}`;
}

/**
 * `str.isprintable()` is false for categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs -
 * with the single exception of U+0020, which repr prints literally.
 */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return hex2(codePoint);
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr(str)`.
 * @param {string} text
 * @returns {string} e.g. `'abc'`, `''`, `'\x1c5'`, `'﻿5'`.
 */
export function strRepr(text) {
  const quote = chooseQuote(text.includes("'"), text.includes('"'));
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint === BACKSLASH) {
      body += '\\\\';
    } else if (codePoint === quote) {
      body += `\\${quoteChar}`;
    } else if (SHORT_ESCAPES.has(codePoint)) {
      body += SHORT_ESCAPES.get(codePoint);
    } else if (codePoint === 0x20 || !NON_PRINTABLE.test(character)) {
      body += character;
    } else {
      body += escapeCodePoint(codePoint);
    }
  }
  return `${quoteChar}${body}${quoteChar}`;
}

/**
 * LAYER 2 - `construct` exceptions.
 *
 * `construct.core.ConstructError` prefixes the message with the path being built, and the
 * result is a two-line `str(exc)`:
 *
 *   Error in path (building) -> field1
 *   struct '<B' error during building, given value 256
 *
 * The `PyException` base from layer 1 already handles multi-line messages, chaining and
 * traceback rendering, so these classes only supply their Python type names.
 */

import { PyException } from '../python/errors.mjs';

export class ConstructError extends PyException {
  /**
   * @param {string} pyType fully qualified Python name.
   * @param {string} message the bare error text.
   * @param {string|null} path e.g. "(building) -> field1"; omitted when unknown.
   */
  constructor(pyType, message, path = null) {
    super(pyType, path ? `Error in path ${path}\n${message}` : message);
    this.path = path;
  }
}

/** Raised when the underlying `struct.pack` format rejects a value. */
export class FormatFieldError extends ConstructError {
  constructor(message, path = null) {
    super('construct.core.FormatFieldError', message, path);
  }
}

/**
 * LAYER 2 - `construct`: the `Struct` combinator, the base `Construct` protocol, and the
 * explicit stand-in for Python's `"name" / subcon` operator.
 *
 * Python's `construct` overloads `/` to wrap a subcon in a `Renamed`. JavaScript has no
 * operator overloading, so this module exposes two equivalent spellings:
 *
 *     field('field1', Int8ul)     // reads like  "field1" / Int8ul
 *     Int8ul.named('field1')      // fluent alternative
 *
 * Traceback fidelity
 * ------------------
 * CPython records a frame for every function an exception unwinds through. Each method
 * here reproduces its own frame with the real `construct/core.py` line number, so the
 * rendered traceback matches the interpreter's byte for byte. The chain for a failing
 * build is: build -> build_stream -> Struct._build -> Renamed._build -> FormatField._build.
 */

import { frame, withFrame } from '../python/errors.mjs';

/** Source file every construct frame reports. */
export const CORE_FILE = 'construct/core.py';

const FRAME_BUILD = frame(CORE_FILE, 452, 'build');
const FRAME_BUILD_STREAM = frame(CORE_FILE, 464, 'build_stream');
const FRAME_STRUCT_BUILD = frame(CORE_FILE, 2260, '_build');
const FRAME_RENAMED_BUILD = frame(CORE_FILE, 2774, '_build');

/** The root path label `build_stream` seeds when building. */
const BUILD_ROOT_PATH = '(building)';

/**
 * Base class for every subcon.
 *
 * Subclasses implement `_build(obj, out, path)`, appending integers 0..255 to `out`
 * (a plain Array - the only byte representation used anywhere in this port).
 */
export class Construct {
  /**
   * `Construct.build(obj)`.
   * @returns {number[]} the built bytes as a plain array of integers.
   */
  build(obj) {
    try {
      return this.buildStream(obj);
    } catch (exc) {
      throw withFrame(exc, FRAME_BUILD);
    }
  }

  /** `Construct.build_stream(obj, stream)` - the stream is our output array. */
  buildStream(obj) {
    const out = [];
    try {
      this._build(obj, out, BUILD_ROOT_PATH);
      return out;
    } catch (exc) {
      throw withFrame(exc, FRAME_BUILD_STREAM);
    }
  }

  /** The explicit equivalent of Python's `"name" / subcon`. */
  named(name) {
    return new Renamed(name, this);
  }

  // eslint-disable-next-line class-methods-use-this, no-unused-vars
  _build(obj, out, path) {
    throw new Error('subcon must implement _build');
  }
}

/**
 * `construct.core.Renamed` - attaches a name to a subcon and extends the error path.
 * This is what `"field1" / Int8ul` evaluates to in Python.
 */
export class Renamed extends Construct {
  constructor(name, subcon) {
    super();
    this.name = name;
    this.subcon = subcon;
  }

  _build(obj, out, path) {
    const namedPath = `${path} -> ${this.name}`;
    try {
      return this.subcon._build(obj, out, namedPath);
    } catch (exc) {
      throw withFrame(exc, FRAME_RENAMED_BUILD);
    }
  }
}

/**
 * `construct.Struct` - builds each named subcon in declaration order, aborting on the
 * first failure (so `--a 300 --b 400` reports `field1`, never `field2`).
 */
export class Struct extends Construct {
  constructor(...subcons) {
    super();
    this.subcons = subcons;
  }

  _build(obj, out, path) {
    try {
      for (const subcon of this.subcons) {
        subcon._build(obj[subcon.name], out, path);
      }
      return obj;
    } catch (exc) {
      throw withFrame(exc, FRAME_STRUCT_BUILD);
    }
  }
}

/**
 * The documented replacement for Python's `"name" / subcon` operator.
 * @param {string} name field name.
 * @param {Construct} subcon the subcon to wrap.
 */
export function field(name, subcon) {
  return new Renamed(name, subcon);
}

/**
 * LAYER 2 - `construct`: fixed-width integer fields.
 *
 * `Int8ul` is `FormatField("<", "B")`: little-endian, unsigned, one byte. The packing rule
 * is spelled out longhand with BigInt arithmetic - take the low 8 bits, shift right,
 * repeat - and the result is a plain Array of integers 0..255. No binary-view or
 * byte-buffer API is involved.
 *
 * Failure path (this is what produces the program's exit-code-1 traceback):
 *   1. `struct.pack` rejects the value and raises `struct.error` at core.py:1165;
 *   2. `FormatField._build` catches it and raises `FormatFieldError` at core.py:1167,
 *      leaving the original as `__context__` - which is why the rendered traceback has
 *      the "During handling of the above exception" section.
 */

import { StructError, frame, withFrame } from '../python/errors.mjs';
import { Construct, CORE_FILE } from './struct.mjs';
import { FormatFieldError } from './errors.mjs';

/** Line where `struct.pack` is called, and where the wrapping error is raised. */
const FRAME_PACK = frame(CORE_FILE, 1165, '_build');
const FRAME_RAISE = frame(CORE_FILE, 1167, '_build');

/**
 * `construct.core.FormatField` - a value packed through Python's `struct` module.
 */
export class FormatField extends Construct {
  /**
   * @param {string} fmtstr the `struct` format string, e.g. "<B".
   * @param {string} packChar the format character alone, e.g. "B".
   * @param {number} length byte width.
   * @param {bigint} min lowest representable value.
   * @param {bigint} max highest representable value.
   */
  constructor(fmtstr, packChar, length, min, max) {
    super();
    this.fmtstr = fmtstr;
    this.packChar = packChar;
    this.length = length;
    this.min = min;
    this.max = max;
  }

  /**
   * `struct.pack(self.fmtstr, value)` for unsigned little-endian formats.
   * @param {bigint} value
   * @returns {number[]} `length` bytes, least significant first.
   * @throws {StructError} exactly as the stdlib does when the value does not fit.
   */
  pack(value) {
    if (value < this.min || value > this.max) {
      throw new StructError(
        `'${this.packChar}' format requires ${this.min} <= number <= ${this.max}`,
      );
    }
    const bytes = [];
    let remaining = value;
    for (let index = 0; index < this.length; index += 1) {
      bytes.push(Number(remaining & 0xffn));
      remaining >>= 8n;
    }
    return bytes;
  }

  _build(value, out, path) {
    let bytes;
    try {
      bytes = this.pack(value);
    } catch (cause) {
      if (!(cause instanceof StructError)) throw cause;
      withFrame(cause, FRAME_PACK);
      const error = new FormatFieldError(
        `struct '${this.fmtstr}' error during building, given value ${value}`,
        path,
      );
      error.pyContext = cause; // Python's implicit exception chaining
      throw withFrame(error, FRAME_RAISE);
    }
    for (const byteValue of bytes) out.push(byteValue);
    return value;
  }
}

/** `construct.Int8ul` - unsigned 8-bit, little-endian. Stateless, hence a singleton. */
export const Int8ul = new FormatField('<B', 'B', 1, 0n, 255n);

/**
 * LAYER 2 - `construct` barrel module.
 *
 * Mirrors the surface `import construct` exposes in Python, so the entry point can write
 * `construct.Struct(...)` / `construct.Int8ul` and read like the original source.
 */

export { Construct, Renamed, Struct, field, CORE_FILE } from './struct.mjs';
export { FormatField, Int8ul } from './format_field.mjs';
export { ConstructError, FormatFieldError } from './errors.mjs';

/**
 * LAYER 3 - CLI: a hand-rolled `argparse` clone.
 *
 * Parsing is done entirely by hand from a token array. The parser performs **no I/O**: help
 * text and error text are raised as a `SystemExit` carrying `{stream, text}` records, so
 * the whole class is testable by asserting on the thrown value.
 *
 * Behaviours reproduced from CPython's argparse:
 *   * `prog` defaults to `basename(sys.argv[0])`.
 *   * `--opt=value` and `--opt value` are both accepted; the last occurrence wins.
 *   * A token is only treated as an option if `_parse_optional` says so. Notably a bare
 *     `-`, an empty string, a negative number (when no option looks like one) and any
 *     token containing a space are values, whereas an unknown `-x`/`--x` is an option -
 *     which is why `--a --b --b 1` reports "expected one argument".
 *   * Unique-prefix abbreviation of long options (`--he` -> `--help`).
 *   * The first `--` ends option parsing; everything after it becomes extras.
 *   * `type=` conversion happens as each value is consumed, so a bad value is reported
 *     before the required-arguments check.
 *   * The required-arguments check runs in `parse_known_args`, i.e. BEFORE the
 *     unrecognized-arguments check in `parse_args`.
 *   * Help fires the instant the option is reached and exits 0.
 */

import { SystemExit } from '../python/errors.mjs';
import { pyInt } from '../python/int_parse.mjs';
import { strRepr } from '../python/bytes_repr.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** argparse formatter defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** A `type=` callable: a display name plus a converter returning a rejection signal. */
export const intType = { name: 'int', convert: pyInt };

/** `basename(path)`, matching how argparse derives `prog` from `sys.argv[0]`. */
export function basename(path) {
  const parts = String(path).split(/[/\\]/);
  return parts[parts.length - 1];
}

export class ArgumentParser {
  /** @param {string} prog program name used in usage, help and error messages. */
  constructor(prog) {
    this.prog = prog;
    /** @type {Array<object>} declaration order drives usage, help and required order. */
    this.actions = [];
    this.optionMap = new Map();
    this.addArgument(['-h', '--help'], {
      kind: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string[]} optionStrings e.g. ['--a'].
   * @param {object} options `kind` ('store'|'help'), `type`, `required`, `metavar`, `help`.
   */
  addArgument(optionStrings, options = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^-+/, '');
    const action = {
      optionStrings,
      dest,
      kind: options.kind ?? 'store',
      type: options.type ?? null,
      required: options.required ?? false,
      metavar: options.metavar ?? dest.toUpperCase(),
      help: options.help ?? null,
    };
    this.actions.push(action);
    for (const optionString of optionStrings) this.optionMap.set(optionString, action);
    return action;
  }

  /** Does this action consume a following value? */
  // eslint-disable-next-line class-methods-use-this
  takesValue(action) {
    return action.kind === 'store';
  }

  /** `-h` / `--a A` - the form used in the usage line (first option string only). */
  usageInvocation(action) {
    const [first] = action.optionStrings;
    return this.takesValue(action) ? `${first} ${action.metavar}` : first;
  }

  /** `-h, --help` / `--a A` - the form used in the options list (all option strings). */
  helpInvocation(action) {
    if (!this.takesValue(action)) return action.optionStrings.join(', ');
    return action.optionStrings.map((o) => `${o} ${action.metavar}`).join(', ');
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation = this.usageInvocation(action);
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  /**
   * Reproduces argparse's column arithmetic: `action_max_length` includes the indent,
   * `help_position = min(action_max_length + 2, max_help_position)` and the invocation is
   * left-padded to `help_position - indent - 2` before two literal spaces and the help.
   * Actions without help text are emitted alone, with no trailing padding.
   */
  formatHelp() {
    const actionMaxLength = Math.max(
      ...this.actions.map((action) => this.helpInvocation(action).length + INDENT),
    );
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const action of this.actions) {
      const invocation = this.helpInvocation(action);
      if (action.help === null) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
      } else {
        out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      }
    }
    return out;
  }

  /** argparse's `error()`: usage line then `prog: error: message`, both on stderr, exit 2. */
  error(message) {
    throw new SystemExit(2, [
      { stream: 'stderr', text: this.formatUsage() },
      { stream: 'stderr', text: `${this.prog}: error: ${message}\n` },
    ]);
  }

  /** argparse's help action: help text on stdout, exit 0. */
  exitWithHelp() {
    throw new SystemExit(0, [{ stream: 'stdout', text: this.formatHelp() }]);
  }

  /** argparse's `_get_option_tuples`: prefix / bundled-short-option candidates. */
  getOptionTuples(token) {
    const matches = [];
    if (token.startsWith('--')) {
      let head = token;
      let explicit = null;
      const equals = token.indexOf('=');
      if (equals >= 0) {
        head = token.slice(0, equals);
        explicit = token.slice(equals + 1);
      }
      for (const [optionString, action] of this.optionMap) {
        if (optionString.startsWith(head)) matches.push({ action, optionString, explicit });
      }
    } else {
      const shortPrefix = token.slice(0, 2);
      const shortExplicit = token.slice(2);
      for (const [optionString, action] of this.optionMap) {
        if (optionString === shortPrefix) {
          matches.push({
            action,
            optionString,
            explicit: shortExplicit === '' ? null : shortExplicit,
          });
        } else if (optionString.startsWith(token)) {
          matches.push({ action, optionString, explicit: null });
        }
      }
    }
    return matches;
  }

  /**
   * argparse's `_parse_optional`.
   * @returns {null|{action: object|null, optionString: string, explicit: string|null}}
   *          `null` means "this token is a value, not an option"; an entry with
   *          `action: null` means "this looks like an option but is unknown".
   */
  parseOptional(token) {
    if (token === '') return null;
    if (token[0] !== '-') return null;

    const exact = this.optionMap.get(token);
    if (exact) return { action: exact, optionString: token, explicit: null };

    if (token.length === 1) return null; // a lone '-' is a value

    const equals = token.indexOf('=');
    if (equals >= 0) {
      const head = token.slice(0, equals);
      const action = this.optionMap.get(head);
      if (action) return { action, optionString: head, explicit: token.slice(equals + 1) };
    }

    const matches = this.getOptionTuples(token);
    if (matches.length > 1) {
      const names = matches.map((m) => m.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // no option looks like a negative number
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicit: null };
  }

  /**
   * argparse's `parse_known_args`.
   * @returns {{namespace: object, extras: string[]}}
   */
  parseKnownArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (this.takesValue(action)) namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let optionsEnded = false;
    let index = 0;

    while (index < argv.length) {
      const token = argv[index];

      if (optionsEnded) {
        extras.push(token);
        index += 1;
        continue;
      }
      if (token === '--') {
        // argparse strips only the first '--'; later ones survive as extras.
        optionsEnded = true;
        index += 1;
        continue;
      }

      const candidate = this.parseOptional(token);
      if (candidate === null || candidate.action === null) {
        extras.push(token); // a stray value, or an unrecognized option
        index += 1;
        continue;
      }

      const { action, optionString, explicit } = candidate;
      index += 1;

      if (action.kind === 'help') {
        if (explicit !== null) {
          this.error(`argument ${optionString}: ignored explicit argument '${explicit}'`);
        }
        this.exitWithHelp();
      }

      let raw;
      if (explicit !== null) {
        raw = explicit;
      } else {
        const next = index < argv.length ? argv[index] : undefined;
        if (next === undefined || this.parseOptional(next) !== null) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        raw = next;
        index += 1;
      }

      const converted = action.type.convert(raw);
      if (!converted.ok) {
        this.error(
          `argument ${optionString}: invalid ${action.type.name} value: ${strRepr(raw)}`,
        );
      }
      namespace[action.dest] = converted.value;
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /** argparse's `parse_args`. Throws `SystemExit` for help and for every error. */
  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }
}

/**
 * The parser this program declares - the direct translation of:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=int, required=True)
 *     parser.add_argument('--b', type=int, required=True)
 *
 * @param {string} prog usually `basename(process.argv[1])`.
 */
export function createParser(prog) {
  const parser = new ArgumentParser(prog);
  parser.addArgument(['--a'], { type: intType, required: true });
  parser.addArgument(['--b'], { type: intType, required: true });
  return parser;
}

