import { bytesRepr } from './lib/python/bytes_repr.mjs';
import { basename, createParser } from './lib/cli/argument_parser.mjs';
import * as construct from './lib/construct/index.mjs';

// ---- def main(): -----------------------------------------------------------------------
function main() {
  const parser = createParser(basename(process.argv[1]));
  const args = parser.parseArgs(process.argv.slice(2));

  const structFormat = new construct.Struct(
    construct.field('field1', construct.Int8ul), // "field1" / Int8ul - define first field
    construct.field('field2', construct.Int8ul), // "field2" / Int8ul - define second field
  );
  const data = structFormat.build({ field1: args.a, field2: args.b });
  process.stdout.write(`${bytesRepr(data)}\n`); // print(data)
}

